export const STR_PROMISE = "Promise";
export const DONE = "done";
export const VALUE = "value";
export const ITERATOR = "iterator";
export const RETURN = "return";
export const REJECTED = "rejected";

/*
 * @nevware21/ts-async
 * https://github.com/nevware21/ts-async
